function chooseFile(accept,callback){const bridge=$('#fileBridge');bridge.accept=accept;bridge.value='';bridge.onchange=()=>{if(bridge.files[0])callback(bridge.files[0])};bridge.click()}
function download(content,name){const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([content],{type:'application/json'}));link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),500)}
function importBackup(file){const reader=new FileReader();reader.onload=()=>{try{const incoming=JSON.parse(reader.result);if(incoming.version===1&&Array.isArray(incoming.profiles)&&incoming.profiles.length){if(confirm('Substituir todos os personagens por este backup?')){profileHub=incoming;profileHub.profiles.forEach(profile=>profile.state=mergeDefaults(profile.state));if(!profileHub.profiles.some(profile=>profile.id===profileHub.activeId))profileHub.activeId=profileHub.profiles[0].id;state=mergeDefaults(activeProfile().state);persistProfiles();toast('Todos os personagens foram restaurados');navigate('profiles')}}else if(incoming.version===3){if(confirm('Substituir somente o personagem atual por este backup antigo?')){state=mergeDefaults(incoming);save('Personagem restaurado');navigate('dashboard')}}else throw new Error()}catch{toast('Este arquivo não é um backup válido')}};reader.readAsText(file)}
function compressImage(file,maxSize=1200,quality=.8){return new Promise((resolve,reject)=>{const image=new Image(),reader=new FileReader();reader.onload=()=>image.src=reader.result;reader.onerror=reject;image.onload=()=>{const scale=Math.min(1,maxSize/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/webp',quality))};reader.readAsDataURL(file)})}

async function loadMarketData(force=false){if(marketData.loading||marketData.loaded&&!force)return;marketData.loading=true;marketData.error='';if(route==='economy')render();try{const [mappingResponse,priceResponse]=await Promise.all([fetch('https://prices.runescape.wiki/api/v1/osrs/mapping',{cache:'no-store'}),fetch('https://prices.runescape.wiki/api/v1/osrs/latest',{cache:'no-store'})]);if(!mappingResponse.ok||!priceResponse.ok)throw new Error('serviço de preços indisponível');const [items,quotes]=await Promise.all([mappingResponse.json(),priceResponse.json()]);marketData.items=Array.isArray(items)?items:[];marketData.prices=quotes.data||{};marketData.loaded=true;marketData.updatedAt=new Date().toISOString()}catch(error){marketData.error=`Não foi possível consultar o GE: ${error.message}.`}finally{marketData.loading=false;if(route==='economy')render()}}
async function loadMarketSeries(itemId){if(marketData.seriesLoading[itemId])return;marketData.seriesLoading[itemId]=true;try{const response=await fetch(`https://prices.runescape.wiki/api/v1/osrs/timeseries?timestep=1h&id=${Number(itemId)}`,{cache:'no-store'});if(!response.ok)throw new Error();const payload=await response.json();marketData.series[itemId]=(payload.data||[]).slice(-24)}catch{marketData.series[itemId]=[]}finally{marketData.seriesLoading[itemId]=false;if(ui.drawer?.type==='geDetail'&&Number(ui.drawer.id)===Number(itemId))render()}}
async function syncGains(){try{const response=await fetch(`https://api.wiseoldman.net/v2/players/${encodeURIComponent(state.username)}/gained?period=week`);if(!response.ok)return;const payload=await response.json(),data=payload.data||{},overall=data.skills?.overall||{},xp=Number(overall.experience?.gained)||0,ehp=Number(overall.ehp?.gained)||Number(data.computed?.ehp?.value?.gained)||0,bossKc=Object.values(data.bosses||{}).reduce((sum,item)=>sum+Math.max(0,Number(item.kills?.gained)||0),0);state.gains={period:'week',xp,ehp,bossKc,lastSync:new Date().toISOString()}}catch{}}
function syncPvmFromSnapshot(snapshot){const metrics=snapshot.bosses||{},changes=[];state.bosses.catalog.forEach(item=>{const matched=findWomBossMetric(item,metrics),data=bossProgress(item.id);if(!matched){data.womSupported=false;return}data.womSupported=true;const kills=Number(matched[1]?.kills);if(!Number.isFinite(kills)||kills<0){data.womUnranked=true;return}const previous=Number(data.kc)||0;data.kc=kills;data.kcSource='wom';data.kcMetric=matched[0];data.kcSyncedAt=new Date().toISOString();data.womUnranked=false;if(kills>0&&data.status==='Nunca tentei')data.status=kills===1?'Primeiro KC':kills>=50?'Consistente':'Aprendendo';if(previous!==kills)changes.push(`${item.name} ${previous}→${kills}`)});const raidMetrics={cox:['chambers_of_xeric','chambers_of_xeric_challenge_mode'],toa:['tombs_of_amascut','tombs_of_amascut_expert'],tob:['theatre_of_blood','theatre_of_blood_hard_mode']};Object.entries(raidMetrics).forEach(([raidId,keys])=>{const values=keys.map(key=>Number(metrics[key]?.kills)).filter(value=>Number.isFinite(value)&&value>=0);if(values.length)state.raids.items[raidId].womKc=values.reduce((sum,value)=>sum+value,0)});return changes}

async function syncAccount(){const buttons=$$('[data-sync], [data-sync-form] button');buttons.forEach(button=>{button.disabled=true;button.textContent='↻ Atualizando...'});try{await fetch(`https://api.wiseoldman.net/v2/players/${encodeURIComponent(state.username)}`,{method:'POST',headers:{'Content-Type':'application/json'}});const response=await fetch(`https://api.wiseoldman.net/v2/players/${encodeURIComponent(state.username)}`);if(!response.ok)throw new Error('Conta não encontrada');const payload=await response.json(),snapshot=payload.latestSnapshot?.data,womType=({regular:'main',ironman:'ironman',hardcore:'hardcore',ultimate:'ultimate'})[payload.type];if(womType)activeProfile().accountType=womType;if(!snapshot)throw new Error('Sem snapshot disponível');const map={attack:'Attack',strength:'Strength',defence:'Defence',hitpoints:'Hitpoints',ranged:'Ranged',prayer:'Prayer',magic:'Magic',cooking:'Cooking',woodcutting:'Woodcutting',fletching:'Fletching',fishing:'Fishing',firemaking:'Firemaking',crafting:'Crafting',smithing:'Smithing',mining:'Mining',herblore:'Herblore',agility:'Agility',thieving:'Thieving',slayer:'Slayer',farming:'Farming',runecrafting:'Runecraft',hunter:'Hunter',construction:'Construction',sailing:'Sailing'};const gained=[];Object.entries(map).forEach(([key,name])=>{const item=skill(name),level=snapshot.skills?.[key]?.level;if(item&&Number.isFinite(level)&&level>0){if(level>item.current)gained.push(`${name} ${item.current}→${level}`);item.current=level;item.xp=snapshot.skills[key].experience||item.xp}});if(state.profileSetupPending){state.skills.forEach(item=>{if(item.target<=item.current)item.target=item.current>=99?99:Math.min(99,Math.ceil((item.current+3)/5)*5)});state.profileSetupPending=false}if(snapshot.skills?.overall?.level)state.total=snapshot.skills.overall.level;const kcChanges=syncPvmFromSnapshot(snapshot);state.lastSync=new Date().toISOString();await syncGains();const details=[...gained,...kcChanges];addHistory('sync','Conta sincronizada',details.length?details.join(', '):'Níveis, KCs e ganhos semanais conferidos.');save(kcChanges.length?`${kcChanges.length} KC(s) atualizada(s)`:'Conta atualizada');render()}catch(error){toast(`Não foi possível atualizar: ${error.message}`);buttons.forEach(button=>button.disabled=false)}}

async function syncQuests(silent=false){
  if(ui.questSyncing)return;
  ui.questSyncing=true;
  if(route==='quests')render();
  try{
    let response,source='WikiSync ao vivo';
    try{response=await fetch(`https://sync.runescape.wiki/runelite/player/${encodeURIComponent(state.username)}/STANDARD`);if(!response.ok)throw new Error()}catch{const snapshot=slug(state.username)==='samurai-jao'?'quest-data.json':`quest-data-${slug(state.username)}.json`;response=await fetch(`${snapshot}?v=${Date.now()}`);source='Snapshot automático do GitHub'}
    if(!response.ok)throw new Error('perfil ainda não disponível no WikiSync');
    const payload=await response.json();
    if(source!=='WikiSync ao vivo'&&String(payload.username).toLowerCase()!==String(state.username).toLowerCase())throw new Error('o snapshot pertence a outro personagem');
    const entries=Object.entries(payload.quests||{}).filter(([name])=>name!=='.');
    if(!entries.length)throw new Error('nenhuma quest encontrada');
    state.quests.items=entries.map(([name,value])=>({name,state:Number(value)}));
    state.quests.lastSync=payload.timestamp||new Date().toISOString();
    state.quests.source=source;
    state.progression.diaries.data=payload.achievement_diaries||{};
    state.progression.diaries.lastSync=payload.timestamp||new Date().toISOString();
    state.progression.diaries.source=source;
    state.progression.combatAchievements.completed=(payload.combat_achievements||[]).map(Number).filter(Number.isFinite);
    state.progression.combatAchievements.lastSync=payload.timestamp||new Date().toISOString();
    state.progression.combatAchievements.source=source;
    const completed=[];
    state.goals.filter(goal=>['quest','diaryTask','diaryTier','combatAchievement','composite'].includes(goal.mode)&&goal.status!=='archived').forEach(goal=>{const progress=Math.round(goalProgress(goal));if(progress>=100&&goal.status!=='done'){goal.status='done';completed.push(goal.title);addHistory('goal',`${goal.title} concluída`,'Conclusão detectada automaticamente pela sincronização.')}else if(progress>0&&goal.status==='planned')goal.status='active'});
    const syncMessage=source==='WikiSync ao vivo'
      ?`Quests, Diaries e Combat Achievements atualizados${completed.length?` · ${completed.length} meta(s) concluída(s)`:''}`
      :`Quests, Diaries e Combat Achievements carregados do snapshot`;
    save(syncMessage,silent);
  }catch(error){if(!silent)toast(`Não foi possível atualizar as quests: ${error.message}`)}finally{ui.questSyncing=false;render()}
}

async function loadWikiCatalog(){if(state.bosses.wikiLoaded)return;try{const response=await fetch('https://oldschool.runescape.wiki/api.php?action=query&format=json&origin=*&list=categorymembers&cmtitle=Category%3ABosses&cmlimit=max&cmtype=page');const payload=await response.json(),known=new Set(state.bosses.catalog.map(item=>item.wiki));(payload.query?.categorymembers||[]).forEach(entry=>{if(!known.has(entry.title)){state.bosses.catalog.push({id:`wiki-${entry.pageid}`,name:entry.title,category:'Catálogo Wiki',wiki:entry.title});known.add(entry.title)}});state.bosses.wikiLoaded=true;save('Catálogo atualizado',true)}catch{}}
async function loadBossImages(force=false){
  if(ui.bossImagesLoading)return 0;
  const refreshCatalog=force||Number(state.bosses.imagesVersion||0)<2;
  const targets=refreshCatalog
    ? state.bosses.catalog.filter(item=>item.wiki||item.name)
    : state.bosses.selected.map(bossId=>state.bosses.catalog.find(item=>item.id===bossId)).filter(item=>item&&!item.image);
  if(!targets.length)return 0;
  ui.bossImagesLoading=true;
  if(route==='pvm'&&!ui.drawer)render();
  let updated=0;
  try{
    for(let start=0;start<targets.length;start+=25){
      const batch=targets.slice(start,start+25),byTitle=new Map(batch.map(item=>[item.wiki||item.name,item]));
      const titles=batch.map(item=>item.wiki||item.name).join('|');
      const response=await fetch(`https://oldschool.runescape.wiki/api.php?action=query&format=json&origin=*&redirects=1&prop=pageimages&piprop=thumbnail%7Coriginal&pithumbsize=180&titles=${encodeURIComponent(titles)}`);
      if(!response.ok)throw new Error(`Wiki ${response.status}`);
      const payload=await response.json();
      (payload.query?.normalized||[]).forEach(entry=>{const item=byTitle.get(entry.from);if(item)byTitle.set(entry.to,item)});
      (payload.query?.redirects||[]).forEach(entry=>{const item=byTitle.get(entry.from);if(item)byTitle.set(entry.to,item)});
      Object.values(payload.query?.pages||{}).forEach(page=>{
        const item=byTitle.get(page.title),source=page.thumbnail?.source||page.original?.source;
        if(item&&source&&item.image!==source){item.image=source;updated++}
      });
    }
    if(refreshCatalog){state.bosses.imagesVersion=2;state.bosses.imagesUpdatedAt=new Date().toISOString()}
    save('Imagens atualizadas',true);
  }catch(error){if(force)toast('Não foi possível atualizar todas as imagens agora. Tente novamente.')}
  finally{ui.bossImagesLoading=false;if(route==='pvm'&&!ui.drawer)render()}
  return updated;
}
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(next===route)return;if(titles[next]){route=next;ui.drawer=null;ui.menu=false;ui.routeEntering=true;window.scrollTo(0,0);render()}});
const osrsPlayer=musicAudio();
osrsPlayer.addEventListener('play',()=>{ui.musicPlaying=true;updateMusicUI()});
osrsPlayer.addEventListener('pause',()=>{ui.musicPlaying=false;updateMusicUI()});
osrsPlayer.addEventListener('ended',()=>selectMusic(ui.musicIndex+1,true));
osrsPlayer.addEventListener('error',()=>{ui.musicPlaying=false;updateMusicUI();toast('Não foi possível carregar esta faixa.')});
loadWikiCatalog().then(loadBossImages);save('Pronto',true);render();syncQuests(true);
